#include <iostream>
#include <vector>
#include <algorithm>

// Function to calculate the number of apples and oranges that land within a given range
std::pair<int, int> countFruits(const std::vector<int>& apples, const std::vector<int>& oranges, int tree, int distance) {
    int numApples = 0;
    int numOranges = 0;

    // Calculate the number of apples that land within the range
    for (const auto& apple : apples) {
        if (std::abs(apple - tree) <= distance) {
            numApples++;
        }
    }

    // Calculate the number of oranges that land within the range
    for (const auto& orange : oranges) {
        if (std::abs(orange - tree) <= distance) {
            numOranges++;
        }
    }

    return std::make_pair(numApples, numOranges);
}

int main() {
    // Input
    int numApples;
    int numOranges;
    std::cin >> numApples >> numOranges;

    std::vector<int> apples(numApples);
    std::vector<int> oranges(numOranges);

    // Input positions of apples and oranges
    for (auto& apple : apples) {
        std::cin >> apple;
    }
    for (auto& orange : oranges) {
        std::cin >> orange;
    }

    int tree;
    int distance;
    std::cin >> tree >> distance;

    // Calculate and display the number of apples and oranges that land within the range
    auto result = countFruits(apples, oranges, tree, distance);
    std::cout << "Apples: " << result.first << std::endl;
    std::cout << "Oranges: " << result.second << std::endl;

    return 0;
}
```

