**Problem Statement**
--------------------

**Problem:** [Birthday Cake Candles](https://www.hackerrank.com/challenges/birthday-cake-candles)

**Description:**
----------------

Given an array of integers representing the heights of birthday candles, determine the number of candles that are taller than all other candles.

**Solution**
------------

### Language: C++
#### Code
```cpp
#include <iostream>
#include <vector>
#include <algorithm>

/**
 * @brief Returns the number of candles taller than all other candles.
 *
 * @param candles Array of integers representing candle heights.
 * @param numCandles Number of candles.
 * @return Number of candles taller than all other candles.
 */
int maxCandles(const std::vector<int>& candles, int numCandles) {
    // Find the maximum height of candles
    int maxHeight = *std::max_element(candles.begin(), candles.end());

    // Count the number of candles with maximum height
    int count = 0;
    for (int i = 0; i < numCandles; ++i) {
        if (candles[i] == maxHeight) {
            ++count;
        }
    }

    return count;
}

int main() {
    int numCandles;
    std::cin >> numCandles;

    std::vector<int> candles(numCandles);
    for (int& candle : candles) {
        std::cin >> candle;
    }

    int result = maxCandles(candles, numCandles);

    std::cout << "Number of candles taller than all other candles: " << result << std::endl;

    return 0;
}
```
