#include <iostream>
#include <vector>
#include <algorithm>

// Function to calculate the minimum distance between the mouse and cat
int minDistance(int mouseX, int mouseY, int catX, int catY, int gridSize) {
    // Calculate the absolute differences in x and y coordinates
    int dx = std::abs(mouseX - catX);
    int dy = std::abs(mouseY - catY);

    // Calculate the minimum distance
    int minDistance = std::min(dx, dy);

    // Return the minimum distance
    return minDistance;
}

// Function to determine the minimum distance between the mouse and cat
int minDistanceBetweenMouseAndCat(int mouseX, int mouseY, int catX, int catY, int gridSize) {
    // Calculate the minimum distance
    int minDistance = minDistance(mouseX, mouseY, catX, catY, gridSize);

    // Return the minimum distance
    return minDistance;
}

// Function to determine the optimal position for the cat to catch the mouse
std::pair<int, int> optimalCatPosition(int mouseX, int mouseY, int catX, int catY, int gridWidth, int gridHeight) {
    // Calculate the minimum distance between the mouse and cat
    int minDistance = minDistanceBetweenMouseAndCat(mouseX, mouseY, catX, catY, gridWidth);

    // Determine the optimal position for the cat to catch the mouse
    if (minDistance == 0) {
        // If the mouse and cat are at the same position, the cat cannot catch the mouse
        return std::make_pair(-1, -1);
    } else if (minDistance == 1) {
        // If the mouse and cat are adjacent to each other, the cat can catch the mouse
        // Determine the optimal position for the cat to catch the mouse
        if (mouseX < catX) {
            // If the mouse is to the left of the cat, the cat should move right
            return std::make_pair(catX + 1, catY);
        } else if (mouseX > catX) {
            // If the mouse is to the right of the cat, the cat should move left
            return std::make_pair(catX - 1, catY);
        } else if (mouseY < catY) {
            // If the mouse is above the cat, the cat should move down
            return std::make_pair(catX, catY + 1);
        } else {
            // If the mouse is below the cat, the cat should move up
            return std::make_pair(catX, catY - 1);
        }
    } else {
        // If the mouse and cat are not adjacent to each other, determine the optimal position for the cat to catch the mouse
        // Calculate the optimal position for the cat to catch the mouse
        if (mouseX < catX) {
            // If the mouse is to the left of the cat, the cat should move right
            return std::make_pair(catX + 1, catY);
        } else if (mouseX > catX) {
            // If the mouse is to the right of the cat, the cat should move left
            return std::make_pair(catX - 1, catY);
        } else if (mouseY < catY) {
            // If the mouse is above the cat, the cat should move down
            return std::make_pair(catX, catY + 1);
        } else {
            // If the mouse is below the cat, the cat should move up
            return std::make_pair(catX, catY - 1);
        }
    }
}

